#include <iostream>
using namespace std;

const int MAXN = 200005;
int a[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if (!(cin >> n >> q)) return 0;
    for (int i = 0; i < n; i++) cin >> a[i];

    while (q--) {
        int x;
        cin >> x;
        int left = 0, right = n;          // 右边界取 n：答案可能越界
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (a[mid] < x) left = mid + 1;
            else right = mid;
        }
        cout << left + 1 << "\n";        // left 是 0 基下标，加 1 变成位置
    }
    return 0;
}
